build.VisitAllChildren<TextNode>(tn => {
    if (tn.Text != null && tn.Text.Contains("Newtonsoft")) {
        Console.WriteLine($"  TextNode: {tn.GetType().Name}: {tn.Text.Substring(0, Math.Min(200, tn.Text.Length))}");
        count++;
    }
});
Console.WriteLine($"Found {count} TextNodes with Newtonsoft");

// Look for the actual error details
Console.WriteLine("\n=== Error parent chain ===");
build.VisitAllChildren<Error>(error => {
    var node = error as BaseNode;
    var parent = node?.Parent;
    string chain = error.Text;
    while (parent != null) {
        chain = $"{parent.GetType().Name}({(parent as NamedNode)?.Name}) > " + chain;
        parent = (parent as BaseNode)?.Parent;
    }
    Console.WriteLine($"  {chain}");
});
